import { Link } from "react-router-dom";
import Teachersidebar from "./Teachersidebar";
import { Routes as Switch, Route } from 'react-router-dom';
import { useState, useEffect } from "react"; // Removed unused 'use' import
import axios from "axios";
import { useParams } from "react-router-dom";

const baseUrl = "http://127.0.0.1:8000/api";

function EditChapter() {
    const [chapterData, setChapterData] = useState({
        "title": '',
        "description": '',
        "video": null, // Changed to null for file handling
        "remarks": '',
        "course": '' // Added course field
    });
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');     
    const { chapter_id } = useParams();
    console.log("Editing Chapter ID:", chapter_id);
    const handleChange = (event) => {
        setChapterData({
            ...chapterData, 
            [event.target.name]: event.target.value
        });
    }

    const handleFileChange = (event) => {
        setChapterData({
            ...chapterData,     
            [event.target.name]: event.target.files[0]
        });
    }

    const submitForm = async (event) => {
        event.preventDefault();
        setIsLoading(true); 
        setError('');
        setSuccess('');
        
        const chapterFormData = new FormData();
        
        chapterFormData.append("title", chapterData.title);
        chapterFormData.append("description", chapterData.description); 
        
        // Only append video if a new file was selected
        if (chapterData.video && typeof chapterData.video !== 'string') {
            chapterFormData.append("video", chapterData.video, chapterData.video.name);
        }   
        
        chapterFormData.append("remarks", chapterData.remarks);
        
        // Include course ID if available
        if (chapterData.course) {
            chapterFormData.append("course", chapterData.course);
        }

        try {
            
            const response = await axios.patch(
                `${baseUrl}/chapter/${chapter_id}`, 
                chapterFormData, 
                {
                    headers: {  
                        'content-type': 'multipart/form-data'
                    }   
                }
            );
            
            setSuccess('Chapter updated successfully!');
            
            // Update local state with response data
            setChapterData({
                ...chapterData,
                title: response.data.title,
                description: response.data.description,
                remarks: response.data.remarks,
                // Don't update video from response as it's a file field
            });
            
        } catch (error) {
            console.log('Update error:', error);
            if (error.response && error.response.data) {
                setError(`Update failed: ${JSON.stringify(error.response.data)}`);
            } else {
                setError('Failed to update chapter. Please try again.');
            }
        } finally {
            setIsLoading(false);
        }
    }

    useEffect(() => {
        const fetchChapter = async () => {
            try {
                const response = await axios.get(`${baseUrl}/course-chapters/${chapter_id}`);
                const chapter = response.data;
                
                // Set state properly, handling file fields
                setChapterData({
                    title: chapter.title,
                    description: chapter.description ,
                    video: chapter.video, // This will be the existing video URL/file path
                    remarks: chapter.remarks,
                    course: chapter.course
                });
                
            } catch (error) {
                console.log('Fetch error:', error);
                setError('Failed to load chapter data.');
            }   
        };
        
        fetchChapter();
    }, []);

    return (
        <div className="container mt-4">
            <div className="row">
                <aside className="col-md-3">
                    <Teachersidebar />
                </aside>
                <section className="col-md-9">
                    <div className="card">
                        <h5 className="card-header">Edit Chapter</h5>
                        <div className="card-body">
                            {/* Success and Error Messages */}
                            {success && (
                                <div className="alert alert-success">{success}</div>
                            )}
                            {error && (
                                <div className="alert alert-danger">{error}</div>
                            )}
                            
                            {/* Show current video if exists */}
                            {chapterData.video && typeof chapterData.video === 'string' && (
                                <div className="mb-3">
                                    <label className="form-label">Current Video</label>
                                    <div>
                                        <video 
                                            width="320" 
                                            height="240" 
                                            controls 
                                            className="mb-2"
                                        >
                                            <source src={chapterData.video} type="video/mp4" />
                                            Your browser does not support the video tag.
                                        </video>
                                        <p className="text-muted small">
                                            Upload a new video below to replace the current one.
                                        </p>
                                    </div>
                                </div>
                            )}
                            
                            <form onSubmit={submitForm}>
                                <div className="mb-3">
                                    <label htmlFor="title" className="form-label">Title</label>
                                    <input 
                                        type="text" 
                                        onChange={handleChange} 
                                        name="title" 
                                        className="form-control" 
                                        id="title"
                                        value={chapterData.title}
                                        required
                                    />
                                </div>
                                <div className="mb-3">
                                    <label htmlFor="description" className="form-label">Description</label>
                                    <textarea 
                                        className="form-control" 
                                        onChange={handleChange} 
                                        name="description"
                                        value={chapterData.description}
                                        rows="4"
                                    />
                                </div>
                                <div className="mb-3">
                                    <label htmlFor="video" className="form-label">
                                        {chapterData.video ? 'Replace Video' : 'Upload Video'}
                                    </label>
                                    <input 
                                        type="file" 
                                        onChange={handleFileChange} 
                                        name="video" 
                                        id="video" 
                                        className="form-control"
                                        accept="video/*"
                                    />
                                    <div className="form-text">
                                        Leave empty to keep the current video
                                    </div>
                                </div>
                                <div className="mb-3">
                                    <label htmlFor="remarks" className="form-label">Remarks</label>
                                    <textarea 
                                        className="form-control" 
                                        onChange={handleChange} 
                                        name="remarks"
                                        value={chapterData.remarks}
                                        rows="3"
                                    />
                                </div>
                                <button 
                                    type="submit" 
                                    className="btn btn-primary"
                                    disabled={isLoading}
                                >
                                    {isLoading ? 'Updating...' : 'Update Chapter'}
                                </button>
                                <Link 
                                    to="/teacher-mycourses" 
                                    className="btn btn-secondary ms-2"
                                >
                                    Cancel
                                </Link>
                            </form>
                        </div>
                    </div>
                </section>
            </div>
        </div>
    );
}

export default EditChapter;
